/**
 * Organization member table component.
 * @module organization-member-table
 * @internal
 */

import type { OrgMember } from '@auth0/universal-components-core';
import * as React from 'react';

import { OrganizationMemberTableActionsColumn } from './organization-member-table-actions-column';

import { formatDate } from '@/components/auth0/my-organization/shared/member-management/members/organization-member-user-details/utils';
import { SearchFilter } from '@/components/auth0/my-organization/shared/member-management/shared/search-filter/search-filter';
import { DataPagination } from '@/components/auth0/shared/data-pagination';
import { DataTable, type Column } from '@/components/auth0/shared/data-table';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import {
  getInitials,
  getMemberDisplayName,
  getRelativeLastLoginLabel,
} from '@/lib/utils/my-organization/member-management/member-management-utils';
import type { OrganizationMemberTableProps } from '@/types/my-organization/member-management/organization-member-table-types';

/**
 * Organization member table component.
 * Displays members with search, filtering, and pagination.
 * @param props - The component props.
 * @param props.members - The list of members to display.
 * @param props.loading - Whether the table is loading.
 * @param props.pagination - Pagination state.
 * @param props.pageSizeOptions - Options for page size selection.
 * @param props.filters - Current filter state.
 * @param props.availableRoles - Available roles for filtering.
 * @param props.onView - Callback when viewing member details.
 * @param props.onAssignRole - Callback when assigning a role to a member.
 * @param props.onRemoveFromOrg - Callback when removing a member from the organization.
 * @param props.onNextPage - Callback when navigating to the next page.
 * @param props.onPreviousPage - Callback when navigating to the previous page.
 * @param props.onPageSizeChange - Callback when page size changes.
 * @param props.onRoleFilterChange - Callback when role filter changes.
 * @param props.onSearchTermChange - Callback when search term changes.
 * @param props.className - Optional CSS class name.
 * @returns The member table component.
 */
export function OrganizationMemberTable({
  members,
  loading = false,
  pagination,
  pageSizeOptions,
  filters,
  customMessages = {},
  availableRoles,
  sortConfig,
  className,
  onSortChange,
  onView,
  onAssignRole,
  onRemoveFromOrg,
  onNextPage,
  onPreviousPage,
  onPageSizeChange,
  onRoleFilterChange,
  onSearchTermChange,
}: OrganizationMemberTableProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  const renderName = React.useCallback((member: OrgMember) => {
    const displayName = getMemberDisplayName(member);
    const initials = getInitials(displayName);
    return (
      <div className="flex items-center gap-4">
        <Avatar>
          <AvatarFallback>{initials}</AvatarFallback>
        </Avatar>
        <div className="min-w-0">
          <div className="truncate font-medium text-primary">{displayName}</div>
          <div className="truncate text-muted-foreground">{member.email ?? '-'}</div>
        </div>
      </div>
    );
  }, []);

  const renderRoles = React.useCallback((member: OrgMember) => {
    const roleNames = member.roles?.map((role) => role.name) ?? [];

    if (roleNames.length === 0) {
      return <span className="text-primary">-</span>;
    }

    const visibleRoles = roleNames.slice(0, 2).join(', ');
    const remainingCount = roleNames.length - 2;
    const fullRoles = roleNames.join(', ');

    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <span className="text-primary">
            {visibleRoles}
            {remainingCount > 0 ? `, +${remainingCount}` : ''}
          </span>
        </TooltipTrigger>
        <TooltipContent>{fullRoles}</TooltipContent>
      </Tooltip>
    );
  }, []);

  const renderLastLogin = React.useCallback(
    (member: OrgMember) => {
      const label = getRelativeLastLoginLabel(member.last_login, t);
      if (!member.last_login || Number.isNaN(new Date(member.last_login).getTime())) {
        return <span className="text-primary">{label}</span>;
      }
      return (
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="text-primary">{label}</span>
          </TooltipTrigger>
          <TooltipContent>{formatDate(member.last_login)}</TooltipContent>
        </Tooltip>
      );
    },
    [t],
  );

  const columns: Column<OrgMember>[] = React.useMemo(
    () => [
      {
        type: 'text',
        accessorKey: 'name',
        title: t('member.table.columns.name'),
        width: '40%',
        enableSorting: false,
        render: renderName,
      },
      {
        type: 'text',
        accessorKey: 'roles',
        title: t('member.table.columns.roles'),
        width: '35%',
        enableSorting: false,
        render: renderRoles,
      },
      {
        type: 'custom',
        accessorKey: 'last_login',
        title: t('member.table.columns.last_login'),
        width: '15%',
        enableSorting: false,
        render: renderLastLogin,
      },
      {
        type: 'actions',
        title: '',
        render: (member) => (
          <OrganizationMemberTableActionsColumn
            member={member}
            onViewDetails={onView}
            onAssignRole={onAssignRole}
            onRemoveFromOrg={onRemoveFromOrg}
          />
        ),
      },
    ],
    [t, onView, onAssignRole, onRemoveFromOrg, renderName, renderRoles, renderLastLogin],
  );

  return (
    <div className={cn('flex flex-col', className)}>
      <SearchFilter
        filters={filters}
        availableRoles={availableRoles}
        activeTab="members"
        onRoleFilterChange={onRoleFilterChange}
        onSearchTermChange={onSearchTermChange}
      />

      <DataTable
        columns={columns}
        data={members}
        loading={loading}
        emptyState={{ title: t('member.table.empty_message') }}
        sortConfig={sortConfig}
        onSortChange={onSortChange}
      />

      {!loading && (members.length > 0 || pagination.hasPreviousPage) && (
        <div className="mt-4">
          <DataPagination
            type="checkpoint"
            paginationState={{
              pageSize: pagination.pageSize,
              currentPage: pagination.currentPage,
              totalItems: pagination.totalItems,
              hasNextPage: pagination.hasNextPage,
              hasPreviousPage: pagination.hasPreviousPage,
            }}
            pageSizeOptions={pageSizeOptions}
            showPageSizeSelector
            showPageInfo
            onNextPage={onNextPage}
            onPreviousPage={onPreviousPage}
            onPageSizeChange={onPageSizeChange}
          />
        </div>
      )}
    </div>
  );
}

/**
 * Modal for assigning roles to a member.
 * @module organization-member-assign-roles-modal
 * @internal
 */

import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Combobox } from '@/components/ui/combobox';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { OrganizationMemberAssignRolesModalProps } from '@/types/my-organization/member-management/organization-member-detail-types';

/**
 * Renders the assign roles dialog for selecting and assigning roles to a member.
 * @param props - Component props
 * @returns The rendered assign roles dialog element
 */
export function OrganizationMemberAssignRolesModal({
  isOpen,
  isLoading = false,
  availableRoles,
  assignedRoles,
  customMessages,
  selectedMember,
  onClose,
  onAssign,
}: OrganizationMemberAssignRolesModalProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);
  const [selectedRoles, setSelectedRoles] = React.useState<string[]>([]);
  const userId = selectedMember?.user_id ?? null;
  const memberRoles = selectedMember?.roles ?? assignedRoles ?? [];

  React.useEffect(() => {
    if (!isOpen) {
      setSelectedRoles([]);
    }
  }, [isOpen]);

  const assignedRoleIds = React.useMemo(
    () => new Set(assignedRoles.map((r) => r.id)),
    [assignedRoles],
  );

  const unassignedRoles = React.useMemo(
    () => availableRoles.filter((r) => !assignedRoleIds.has(r.id)),
    [availableRoles, assignedRoleIds],
  );

  const handleOpenChange = React.useCallback(
    (open: boolean) => {
      if (!open) {
        setSelectedRoles([]);
        onClose();
      }
    },
    [onClose],
  );

  const handleSubmit = React.useCallback(() => {
    if (selectedRoles.length > 0) {
      onAssign(selectedRoles, memberRoles, userId);
    }
  }, [selectedRoles, onAssign, memberRoles, userId]);

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="mb-4">{t('member.detail.roles.assign_modal.title')}</DialogTitle>
        </DialogHeader>

        <div className="flex flex-col gap-3 w-full">
          {unassignedRoles.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              {t('member.detail.roles.assign_modal.no_roles_available')}
            </p>
          ) : (
            <>
              <Label>{t('member.detail.roles.assign_modal.roles_label')}</Label>
              <Combobox
                multiple
                options={unassignedRoles.map((r) => ({ value: r.id, label: r.name }))}
                value={selectedRoles}
                onChange={(val) => setSelectedRoles(Array.isArray(val) ? val : [val])}
                placeholder={t('member.detail.roles.assign_modal.roles_placeholder')}
                disabled={isLoading}
                showSelectedCount
              />
            </>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} disabled={isLoading}>
            {t('member.detail.roles.assign_modal.cancel_button')}
          </Button>
          <Button
            onClick={handleSubmit}
            disabled={isLoading || selectedRoles.length === 0 || unassignedRoles.length === 0}
          >
            {t('member.detail.roles.assign_modal.submit_button')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import type { OrgMember } from '@auth0/universal-components-core';

/**
 * Formats an ISO date string into a human-readable locale string.
 * @param dateStr - ISO date string to format
 * @returns Formatted date string, or an em dash if the input is absent
 */
export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  return new Date(dateStr).toLocaleString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

/**
 * Builds the list of display fields for an org member's detail view.
 * @param member - The organization member whose details to display
 * @param t - Translation function used to look up field labels
 * @returns Array of label/value/copyable field descriptors
 */
export function buildMemberDetailFields(member: OrgMember, t: (key: string) => string) {
  const phoneNumber = member.phone_number ?? '';
  const firstIdentity = member.identities?.[0];
  const provider =
    firstIdentity?.provider && firstIdentity?.connection
      ? `${firstIdentity.provider}, ${firstIdentity.connection}`
      : '';

  return [
    { label: t('member.detail.user_details.name'), value: member.name ?? '—', copyable: false },
    { label: t('member.detail.user_details.email'), value: member.email ?? '—', copyable: true },
    {
      label: t('member.detail.user_details.phone_number'),
      value: phoneNumber || '—',
      copyable: !!phoneNumber,
    },
    { label: t('member.detail.user_details.provider'), value: provider || '—', copyable: false },
    {
      label: t('member.detail.user_details.created_at'),
      value: formatDate(member.created_at),
      copyable: false,
    },
    {
      label: t('member.detail.user_details.last_login'),
      value: formatDate(member.last_login),
      copyable: false,
    },
  ];
}

/**
 * Organization invitation create modal component.
 * @module organization-invitation-create-modal
 */

import { createInvitationCreateSchema } from '@auth0/universal-components-core';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Combobox } from '@/components/ui/combobox';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { TextFieldGroup } from '@/components/ui/text-field-group';
import type { ChipItem } from '@/components/ui/text-field-group';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { OrganizationInvitationCreateModalProps } from '@/types/my-organization/member-management/organization-invitation-table-types';

/**
 * Modal for creating a new invitation.
 * Supports multiple email addresses, role selection, and provider selection.
 * Validation rules can be overridden via the `schema` prop.
 *
 * @param props - The component props.
 * @param props.isOpen - Whether the modal is open.
 * @param props.isLoading - Whether the form is loading.
 * @param props.customMessages - Custom translation messages.
 * @param props.availableRoles - Available roles for selection.
 * @param props.availableProviders - Available identity providers.
 * @param props.inviterName - Name of the person sending the invitation.
 * @param props.schema - Schema overrides for validation (email regex, maxEmails, error messages).
 * @param props.onClose - Callback when modal is closed.
 * @param props.onCreate - Callback when invitation is created.
 * @param props.className - Optional CSS class name.
 * @returns The modal component.
 */
export function OrganizationInvitationCreateModal({
  isOpen,
  isLoading = false,
  customMessages = {},
  availableRoles = [],
  availableProviders = [],
  inviterName,
  schema,
  onClose,
  onCreate,
  className,
}: OrganizationInvitationCreateModalProps): React.JSX.Element {
  const { t } = useTranslator('member_management', customMessages);

  const validationConfig = React.useMemo(
    () => createInvitationCreateSchema(schema, t('invitation.create.email_invalid_error')),
    [schema, t],
  );

  const [emailInput, setEmailInput] = React.useState('');
  const [emailChips, setEmailChips] = React.useState<ChipItem[]>([]);
  const [selectedRoles, setSelectedRoles] = React.useState<string[]>([]);
  const [selectedProvider, setSelectedProvider] = React.useState<string | undefined>();
  const [emailError, setEmailError] = React.useState<string | undefined>();

  const resetForm = React.useCallback(() => {
    setEmailInput('');
    setEmailChips([]);
    setSelectedRoles([]);
    setSelectedProvider(undefined);
    setEmailError(undefined);
  }, []);

  React.useEffect(() => {
    if (!isOpen) {
      resetForm();
    }
  }, [isOpen, resetForm]);

  const handleEmailInputChange = React.useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setEmailInput(e.target.value);
    setEmailError(undefined);
  }, []);

  const hasInvalidChips = React.useMemo(
    () => emailChips.some((chip) => chip.variant === 'destructive'),
    [emailChips],
  );

  const handleEmailChipAdd = React.useCallback(
    (value: string) => {
      const trimmedEmail = value.trim().replace(/,/g, '');

      if (!trimmedEmail) return;

      if (emailChips.length >= validationConfig.maxEmails) {
        setEmailError(t('invitation.create.email_limit_error'));
        return;
      }

      if (emailChips.some((chip) => chip.value === trimmedEmail)) {
        setEmailError(t('invitation.create.email_duplicate_error'));
        return;
      }

      const result = validationConfig.emailSchema.safeParse(trimmedEmail);
      if (!result.success) {
        setEmailChips((prev) => [
          ...prev,
          { label: trimmedEmail, value: trimmedEmail, variant: 'destructive' },
        ]);
        setEmailInput('');
        setEmailError(t('invitation.create.email_invalid_error'));
        return;
      }

      setEmailChips((prev) => [...prev, { label: trimmedEmail, value: trimmedEmail }]);
      setEmailInput('');
      setEmailError(undefined);
    },
    [emailChips, validationConfig, t],
  );

  const handleEmailChipRemove = React.useCallback((value: string) => {
    setEmailChips((prev) => {
      const updated = prev.filter((chip) => chip.value !== value);
      if (!updated.some((chip) => chip.variant === 'destructive')) {
        setEmailError(undefined);
      }
      return updated;
    });
  }, []);

  const handleRoleChange = React.useCallback((value: string | string[]) => {
    setSelectedRoles(Array.isArray(value) ? value : value ? [value] : []);
  }, []);

  const handleProviderChange = React.useCallback((value: string) => {
    setSelectedProvider(value || undefined);
  }, []);

  const handleSubmit = React.useCallback(() => {
    const finalEmails = emailChips
      .filter((chip) => chip.variant !== 'destructive')
      .map((chip) => chip.value);

    if (emailInput.trim()) {
      const trimmedEmail = emailInput.trim();
      const result = validationConfig.emailSchema.safeParse(trimmedEmail);
      if (result.success && !finalEmails.includes(trimmedEmail)) {
        finalEmails.push(trimmedEmail);
      } else if (!result.success) {
        setEmailError(t('invitation.create.email_invalid_error'));
        return;
      }
    }

    if (finalEmails.length === 0) {
      setEmailError(t('invitation.create.email_required_error'));
      return;
    }

    onCreate({
      invitees: finalEmails.map((email) => ({
        email,
        roles: selectedRoles.length > 0 ? selectedRoles : undefined,
      })),
      identity_provider_id: selectedProvider,
      ...(inviterName && { inviter: { name: inviterName } }),
    });
  }, [
    emailChips,
    emailInput,
    validationConfig,
    selectedRoles,
    selectedProvider,
    inviterName,
    onCreate,
    t,
  ]);

  const handleClose = React.useCallback(() => {
    resetForm();
    onClose();
  }, [onClose, resetForm]);

  const canSubmit = React.useMemo(
    () =>
      !hasInvalidChips &&
      (emailChips.length > 0 ||
        (emailInput.trim() !== '' &&
          validationConfig.emailSchema.safeParse(emailInput.trim()).success)),
    [emailChips.length, emailInput, validationConfig, hasInvalidChips],
  );

  const roleOptions = React.useMemo(
    () => availableRoles.map((role) => ({ label: role.name, value: role.id })),
    [availableRoles],
  );

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className={className}>
        <DialogHeader>
          <DialogTitle>{t('invitation.create.title')}</DialogTitle>
          <DialogDescription>{t('invitation.create.description')}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="email">{t('invitation.create.email_label')}*</Label>
            <TextFieldGroup
              id="email"
              placeholder={t('invitation.create.email_placeholder')}
              value={emailInput}
              onChange={handleEmailInputChange}
              disabled={isLoading}
              variant={emailError || hasInvalidChips ? 'error' : 'default'}
              chips={emailChips}
              onChipAdd={handleEmailChipAdd}
              onChipRemove={handleEmailChipRemove}
              summarizeChips={false}
            />
            <p className="text-sm text-muted-foreground">{t('invitation.create.email_helper')}</p>
            {emailError && <p className="text-sm text-destructive-foreground">{emailError}</p>}
          </div>

          <div className="space-y-2">
            <Label htmlFor="roles">{t('invitation.create.roles_label')}</Label>
            <Combobox
              value={selectedRoles}
              onChange={handleRoleChange}
              options={roleOptions}
              placeholder={t('invitation.create.roles_placeholder')}
              disabled={isLoading || availableRoles.length === 0}
              multiple
              showSelectedCount
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="provider">{t('invitation.create.provider_label')}</Label>
            <Select
              value={selectedProvider ?? ''}
              onValueChange={handleProviderChange}
              disabled={isLoading || availableProviders.length === 0}
            >
              <SelectTrigger id="provider">
                <SelectValue placeholder={t('invitation.create.provider_placeholder')} />
              </SelectTrigger>
              <SelectContent>
                {availableProviders.map((provider) => (
                  <SelectItem key={provider.id} value={provider.id}>
                    {provider.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              {t('invitation.create.provider_helper')}
            </p>
          </div>
        </div>

        <DialogFooter>
          <Button type="button" variant="outline" onClick={handleClose} disabled={isLoading}>
            {t('invitation.create.cancel_button')}
          </Button>
          <Button type="button" onClick={handleSubmit} disabled={isLoading || !canSubmit}>
            {isLoading ? t('invitation.create.creating') : t('invitation.create.submit_button')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Search and filter component for invitations.
 * @module search-filter
 * @internal
 */

import { X } from 'lucide-react';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import { Search } from '@/components/ui/search';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useTranslator } from '@/hooks/shared/use-translator';
import type { SearchFilterProps } from '@/types/my-organization/member-management/organization-invitation-table-types';

/**
 * Filter bar for invitation table.
 * Shows a right-aligned role filter dropdown with a reset button.
 * @param props - The component props.
 * @param props.filters - Current filter state.
 * @param props.availableRoles - Available roles for filtering.
 * @param props.customMessages - Custom translation messages.
 * @param props.className - Optional CSS class name.
 * @param props.activeTab - The currently active tab (members or invitations).
 * @param props.onRoleFilterChange - Callback fired when role filter changes.
 * @param props.onSearchTermChange - Callback fired when search term changes.
 * @returns The search and filter component.
 */
export function SearchFilter({
  filters,
  availableRoles = [],
  customMessages = {},
  className,
  activeTab,
  onRoleFilterChange,
  onSearchTermChange,
}: SearchFilterProps): React.JSX.Element | null {
  const { t } = useTranslator('member_management', customMessages);
  const [searchTerm, setSearchTerm] = React.useState('');

  const handleRoleFilterChange = React.useCallback(
    (value: string) => {
      onRoleFilterChange?.(value === 'all' ? undefined : value);
    },
    [onRoleFilterChange],
  );

  const handleKeyDownSearch = React.useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (event.key === 'Escape') {
        setSearchTerm('');
      }
      if (event.key === 'Enter') {
        onSearchTermChange?.(searchTerm);
      }
    },
    [searchTerm, onSearchTermChange],
  );

  const handleReset = React.useCallback(() => {
    onRoleFilterChange?.(undefined);
  }, [onRoleFilterChange]);

  const hasActiveFilter = !!filters?.roleId;

  if (availableRoles.length === 0) {
    return null;
  }

  return (
    <div className={className ?? 'mt-8 mb-6 flex items-center justify-end gap-2'}>
      {activeTab === 'members' && (
        <Search
          className="flex-1"
          placeholder={t('member.table.search_placeholder')}
          value={searchTerm}
          onChange={setSearchTerm}
          onKeyDown={handleKeyDownSearch}
        />
      )}
      <Select value={filters?.roleId ?? 'all'} onValueChange={handleRoleFilterChange}>
        <SelectTrigger
          className="w-auto min-w-45"
          aria-label={t('invitation.table.filter_by_role')}
        >
          <span className="text-muted-foreground mr-1">
            {t('invitation.table.filter_by_role')}:
          </span>
          <SelectValue placeholder={t('invitation.table.all_roles')} />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="all">{t('invitation.table.all_roles')}</SelectItem>
          {availableRoles.map((role) => (
            <SelectItem key={role.id} value={role.id}>
              {role.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Button variant="outline" onClick={handleReset} disabled={!hasActiveFilter} className="gap-1">
        {t('invitation.table.reset_filter')}
        <X className="h-4 w-4" />
      </Button>
    </div>
  );
}

/**
 * Data table pagination component.
 * @module data-pagination
 * @internal
 */

import { useMemo, useRef, useEffect } from 'react';

import {
  Pagination,
  PaginationContent,
  PaginationItem,
  PaginationPrevious,
  PaginationNext,
} from '@/components/auth0/shared/pagination';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { cn } from '@/lib/utils';

export interface DataPaginationLabels {
  showing: string;
  to: string;
  of: string;
  results: string;
  totalResults: string;
  show: string;
  perPage: string;
  previous: string;
  next: string;
  goToPage: string;
  goToPrevious: string;
  goToNext: string;
  morePages: string;
}

export const defaultLabels: DataPaginationLabels = {
  showing: 'Showing',
  to: 'to',
  of: 'of',
  results: '',
  totalResults: 'total results',
  show: '',
  perPage: 'per page',
  previous: '',
  next: '',
  goToPage: 'Go to page {page}',
  goToPrevious: 'Go to previous page',
  goToNext: 'Go to next page',
  morePages: 'More pages',
};

export interface RegularPaginationState {
  currentPage: number;
  totalPages: number;
  pageSize: number;
  totalItems: number;
  maxVisiblePages?: number;
}

export interface CheckpointPaginationState {
  pageSize: number;
  currentPage?: number;
  totalItems?: number;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
}

export interface DataPaginationProps {
  type: 'regular' | 'checkpoint';
  paginationState: RegularPaginationState | CheckpointPaginationState;
  pageSizeOptions?: number[];
  showPageSizeSelector?: boolean;
  showPageInfo?: boolean;
  className?: string;
  labels?: Partial<DataPaginationLabels>;
  locale?: string;
  onPageChange?: (page: number) => void;
  onPageSizeChange?: (pageSize: number) => void;
  onNextPage?: () => void;
  onPreviousPage?: () => void;
}

interface PageRangeInfoProps {
  totalItems: number;
  currentPage: number;
  pageSize: number;
  locale?: string;
  labels: DataPaginationLabels;
}

const formatNumber = (num: number | undefined | null, locale?: string): string => {
  if (num === null || num === undefined || isNaN(num)) {
    return '0';
  }

  const resolvedLocale =
    locale ?? (typeof navigator !== 'undefined' ? navigator.language : 'en-US');
  return num.toLocaleString(resolvedLocale);
};

const getPageRange = (
  totalItems: number,
  currentPage: number,
  pageSize: number,
  locale?: string,
): { start: string; end: string } => {
  const start = totalItems === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const end = Math.min(currentPage * pageSize, totalItems);
  return {
    start: formatNumber(start, locale),
    end: formatNumber(end, locale),
  };
};

/**
 * Renders the page range info.
 *
 * @param props - Component props.
 * @param props.totalItems - Total number of items.
 * @param props.currentPage - Current page number.
 * @param props.pageSize - Number of items per page.
 * @param props.locale - Locale identifier for number formatting.
 * @param props.labels - Label text configuration.
 * @returns JSX element displaying the page range info.
 */
function PageRangeInfo({ totalItems, currentPage, pageSize, locale, labels }: PageRangeInfoProps) {
  const range = getPageRange(totalItems, currentPage, pageSize, locale);
  return (
    <>
      {labels.showing}{' '}
      <span className="font-medium text-foreground">
        {range.start}-{range.end}
      </span>{' '}
      {labels.of}{' '}
      <span className="font-medium text-foreground">{formatNumber(totalItems, locale)}</span>
      {labels.results && <> {labels.results}</>}
    </>
  );
}

/**
 *
 * @param props - Component props.
 * @param props.type - The type of the item
 * @param props.paginationState - Current pagination state
 * @param props.pageSizeOptions - Available page size options
 * @param props.showPageSizeSelector - Whether to show page size selector
 * @param props.showPageInfo - Whether to show page info
 * @param props.className - Optional CSS class name for styling
 * @param props.labels - Label text configuration
 * @param props.locale - Locale identifier
 * @param props.onPageChange - Callback fired when page changes
 * @param props.onPageSizeChange - Callback fired when page size changes
 * @param props.onNextPage - Callback fired when navigating to next page
 * @param props.onPreviousPage - Callback fired when navigating to previous page
 * @returns JSX element
 */
export function DataPagination({
  type,
  paginationState,
  pageSizeOptions,
  showPageSizeSelector = false,
  showPageInfo = false,
  className,
  labels: customLabels,
  locale,
  onPageChange,
  onPageSizeChange,
  onNextPage,
  onPreviousPage,
}: DataPaginationProps) {
  const labels = useMemo(() => ({ ...defaultLabels, ...customLabels }), [customLabels]);
  const ariaLiveRegionRef = useRef<HTMLDivElement | null>(null);

  const isRegular = type === 'regular';
  const regularState = isRegular ? (paginationState as RegularPaginationState) : null;
  const checkpointState = !isRegular ? (paginationState as CheckpointPaginationState) : null;

  const currentPageSize = paginationState ? paginationState.pageSize : undefined;

  const shouldShowPageSizeSelector = showPageSizeSelector;

  const allPageSizeOptions = useMemo(() => {
    if (!shouldShowPageSizeSelector || !pageSizeOptions || currentPageSize === undefined) return [];
    const uniqueOptions = new Set([...pageSizeOptions, currentPageSize]);
    return Array.from(uniqueOptions).sort((a, b) => a - b);
  }, [shouldShowPageSizeSelector, pageSizeOptions, currentPageSize]);

  useEffect(() => {
    if (ariaLiveRegionRef.current) {
      if (isRegular && regularState) {
        ariaLiveRegionRef.current.textContent = `Page ${regularState.currentPage} loaded.`;
      } else if (checkpointState) {
        ariaLiveRegionRef.current.textContent = 'Content loaded.';
      }
    }
  }, [type, paginationState, isRegular, regularState, checkpointState]);

  if (!paginationState) {
    return null;
  }

  const safeCurrentPageSize = currentPageSize as number;

  return (
    <div
      className={cn('flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-end', className)}
    >
      <div
        ref={ariaLiveRegionRef}
        className="sr-only"
        role="status"
        aria-live="polite"
        aria-atomic="true"
      />

      {showPageInfo && (
        <div className="text-sm text-foreground whitespace-nowrap sm:mr-auto">
          {isRegular && regularState ? (
            <PageRangeInfo
              totalItems={regularState.totalItems}
              currentPage={regularState.currentPage}
              pageSize={regularState.pageSize}
              locale={locale}
              labels={labels}
            />
          ) : checkpointState?.totalItems !== undefined &&
            checkpointState?.currentPage !== undefined ? (
            <PageRangeInfo
              totalItems={checkpointState.totalItems}
              currentPage={checkpointState.currentPage}
              pageSize={checkpointState.pageSize}
              locale={locale}
              labels={labels}
            />
          ) : checkpointState?.totalItems !== undefined ? (
            <>
              <span className="font-medium text-foreground">
                {formatNumber(checkpointState.totalItems, locale)}
              </span>{' '}
              <span>{labels.totalResults}</span>
            </>
          ) : null}
        </div>
      )}

      <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
        {shouldShowPageSizeSelector && allPageSizeOptions.length > 0 && (
          <div className="flex items-center justify-center gap-2 whitespace-nowrap sm:justify-start">
            {labels.show && <span className="text-sm text-foreground">{labels.show}</span>}
            <Select
              value={safeCurrentPageSize.toString()}
              onValueChange={(value) => onPageSizeChange?.(Number(value))}
            >
              <SelectTrigger className="w-20 h-9">
                <SelectValue placeholder={formatNumber(safeCurrentPageSize, locale)} />
              </SelectTrigger>
              <SelectContent>
                {allPageSizeOptions.map((size) => (
                  <SelectItem key={size} value={size.toString()}>
                    {formatNumber(size, locale)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <span className="text-sm text-foreground">{labels.perPage}</span>
          </div>
        )}

        <Pagination role="navigation" aria-label="Pagination Navigation">
          <PaginationContent>
            {isRegular && regularState ? (
              <>
                <PaginationItem>
                  <PaginationPrevious
                    label={labels.previous}
                    onClick={() => onPageChange?.(Math.max(1, regularState.currentPage - 1))}
                    className={cn(
                      regularState.currentPage <= 1 &&
                        'pointer-events-none opacity-50 text-foreground',
                    )}
                    aria-label={labels.goToPrevious}
                    aria-disabled={regularState.currentPage <= 1}
                  />
                </PaginationItem>

                <PaginationItem>
                  <PaginationNext
                    label={labels.next}
                    onClick={() =>
                      onPageChange?.(
                        Math.min(regularState.totalPages, regularState.currentPage + 1),
                      )
                    }
                    className={cn(
                      regularState.currentPage >= regularState.totalPages &&
                        'pointer-events-none opacity-50 text-foreground',
                    )}
                    aria-label={labels.goToNext}
                    aria-disabled={regularState.currentPage >= regularState.totalPages}
                  />
                </PaginationItem>
              </>
            ) : checkpointState ? (
              <>
                <PaginationItem>
                  <PaginationPrevious
                    label={labels.previous}
                    onClick={() => onPreviousPage?.()}
                    className={cn(
                      !checkpointState.hasPreviousPage &&
                        'pointer-events-none opacity-50 text-foreground',
                    )}
                    aria-label={labels.goToPrevious}
                    aria-disabled={!checkpointState.hasPreviousPage}
                  />
                </PaginationItem>

                <PaginationItem>
                  <PaginationNext
                    label={labels.next}
                    onClick={() => onNextPage?.()}
                    className={cn(
                      !checkpointState.hasNextPage &&
                        'pointer-events-none opacity-50 text-foreground',
                    )}
                    aria-label={labels.goToNext}
                    aria-disabled={!checkpointState.hasNextPage}
                  />
                </PaginationItem>
              </>
            ) : null}
          </PaginationContent>
        </Pagination>
      </div>
    </div>
  );
}

/**
 * Data table with sorting and actions.
